// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';


export type LiquidPowderSealProps = Record<string, any>;

const LiquidPowderSeal: React.FC<LiquidPowderSealProps> = ({
  backgroundColor = "#121212",
  transparentBackground = false,
  durationInSeconds = 8,
  surfaceColor = "#2A2A2A",
  liquidColor = "#00F0FF",
  powderColor = "#FFFFFF",
  dropScale = 1.2,
  powderAmount = 400,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Key Milestones
  const surfaceY = height * 0.75;
  const dropFallStart = 15;
  const dropFallEnd = 45;
  const isFalling = frame < dropFallEnd;

  const powderShowerStart = dropFallEnd + 20;
  const powderShowerEnd = powderShowerStart + 60;

  // --- Liquid Drop Logic ---
  const dropProgress = interpolate(frame, [dropFallStart, dropFallEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const fallY = interpolate(
    frame,
    [dropFallStart, dropFallEnd],
    [-150, surfaceY],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.in(Easing.poly(3)),
    }
  );

  const stretchY = interpolate(dropProgress, [0, 1], [1, 1.6]);
  const stretchX = interpolate(dropProgress, [0, 1], [1, 0.8]);

  // Post-impact: squashes and spreads
  const squashH = spring({
    frame: frame - dropFallEnd,
    fps,
    config: { damping: 12, mass: 0.5, stiffness: 150 },
  });
  const spreadW = spring({
    frame: frame - dropFallEnd,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  const targetSpreadWidth = dropScale * width * 0.4;
  const postWidth = 60 + spreadW * (targetSpreadWidth - 60);
  const postHeight = Math.max(10, 60 - squashH * 40); // Settles around 20

  // --- Seal / Crust Logic ---
  // The powder crust forms seamlessly as the powder showers from left to right
  const clipProgress = interpolate(
    frame,
    [powderShowerStart + 15, powderShowerEnd + 5],
    [0, 100],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Background/Scene Base */}
      <AbsoluteFill style={{ transition: "none" }} />

      {/* Surface Block */}
      <div
        style={{
          position: "absolute",
          top: surfaceY,
          left: 0,
          width: "100%",
          height: height - surfaceY,
          backgroundColor: surfaceColor,
          transition: "none",
        }}
      />

      {/* Falling Droplet (Teardrop SVG) */}
      <div
        style={{
          position: "absolute",
          top: fallY,
          left: width / 2,
          width: 60,
          height: 60,
          transform: `translate(-50%, -100%) scale(${stretchX}, ${stretchY})`,
          opacity: isFalling ? 1 : 0,
          color: liquidColor,
          transition: "none",
        }}
      >
        <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", display: "block" }}>
          {/* A perfect teardrop path */}
          <path d="M50 0 C60 30, 90 50, 90 75 A40 40 0 0 1 10 75 C10 50, 40 30, 50 0 Z" fill="currentColor" />
        </svg>
      </div>

      {/* Main Liquid Puddle (Squash/Spread) */}
      <div
        style={{
          position: "absolute",
          top: surfaceY,
          left: width / 2,
          transform: "translate(-50%, -100%)",
          width: postWidth,
          height: postHeight,
          borderRadius: "50%",
          backgroundColor: liquidColor,
          boxShadow: `0 0 ${40 * (1 - (clipProgress / 100))}px ${liquidColor}90`,
          opacity: isFalling ? 0 : 1,
          transition: "none",
          overflow: "hidden", // Constrains the seal layer
        }}
      >
        {/* The Sealing Crust inside the liquid puddle */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            backgroundColor: powderColor,
            clipPath: `inset(0 ${100 - clipProgress}% 0 0)`,
            transition: "none",
          }}
        />
      </div>

      {/* Powder Particles Falling from Above */}
      {Array.from({ length: powderAmount }).map((_, i) => {
        // Distribute particle targets around the puddle center
        const rX = (random(`x-${i}`) - 0.5) * 2;
        const clusterFactor = Math.sign(rX) * Math.pow(Math.abs(rX), 1.2);
        const targetX = width / 2 + clusterFactor * (targetSpreadWidth / 2) * 1.1;
        
        // Progress powder shower from left to right across the puddle width
        const normalizedX = (targetX - (width / 2 - targetSpreadWidth / 2)) / targetSpreadWidth;
        const passFrame = powderShowerStart + normalizedX * (powderShowerEnd - powderShowerStart);
        
        const spawnDelay = (random(`spawn-${i}`) - 0.5) * 8;
        const startFrame = passFrame + spawnDelay;

        if (frame < startFrame) return null;

        const duration = 15 + random(`dur-${i}`) * 10;
        const endFrame = startFrame + duration;

        const pY = interpolate(
          frame,
          [startFrame, endFrame],
          [surfaceY - 250 - random(`h-${i}`) * 100, surfaceY - random(`stack-${i}`) * 5],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.in(Easing.quad) }
        );

        // Drift slightly horizontally as it falls
        const pX = targetX + interpolate(
          frame,
          [startFrame, endFrame],
          [(random(`drift-${i}`) - 0.5) * 40, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const pOpacity = interpolate(
          frame,
          [startFrame, startFrame + 3, endFrame, endFrame + 15],
          [0, 1, 1, 0],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: pX,
              top: pY,
              width: 3 + random(`size-${i}`) * 3,
              height: 3 + random(`size-${i}`) * 3,
              borderRadius: "50%",
              backgroundColor: powderColor,
              opacity: pOpacity,
              transform: "translate(-50%, -100%)",
              transition: "none",
              zIndex: 5,
            }}
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default LiquidPowderSeal;